<script setup lang="ts">import {computed,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {Sparkles,Mail} from 'lucide-vue-next';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import Tabs from '@/components/zs/Tabs.vue';import ScoreBadge from '@/components/crm/ScoreBadge.vue';import AIInsightCard from '@/components/crm/AIInsightCard.vue';import ActivityTimeline from '@/components/crm/ActivityTimeline.vue';import SidePanel from '@/components/zs/SidePanel.vue';import StatusBadge from '@/components/zs/StatusBadge.vue';import ZButton from '@/components/zs/ZButton.vue';import {useCrmData} from '@/composables/useCrmData';import {setPageMeta} from '@/lib/page-meta';setPageMeta('Lead Workspace','Enrichment, scoring, activity and outreach in one lead workspace.');const route=useRoute(),router=useRouter(),d=useCrmData(),tab=ref('Overview'),processing=ref(false),accepted=ref(false),mailOpen=ref(false);const lead=computed(()=>(d.leads.data.value??[]).find(x=>x.id===route.params.id)),acts=computed(()=>(d.activities.data.value??[]).filter(x=>x.leadId===lead.value?.id)),emails=computed(()=>(d.emails.data.value??[]).filter(x=>x.leadId===lead.value?.id)),selected=ref<typeof emails.value[number]|null>(null);function enrich(){processing.value=true;tab.value='AI Enrichment';setTimeout(()=>processing.value=false,1000)}</script>
<template><AppShell><template v-if="lead"><PageHeader :title="lead.name" :description="`${lead.title} at ${lead.company}`"><template #actions><ZButton variant="outline" @click="enrich"><Sparkles class="size-3.5"/>{{lead.enrichment.state==='enriched'?'Re-run enrichment':'Run enrichment'}}</ZButton><ZButton @click="router.push({path:'/outreach/compose',query:{lead:lead.id}})"><Mail class="size-3.5"/>Generate outreach</ZButton></template></PageHeader><div class="mb-3 grid gap-3 sm:grid-cols-3"><div class="panel p-4"><p class="label-caps">Fit score</p><p class="num mt-2 text-2xl font-semibold text-content">{{lead.score.fit}}</p></div><div class="panel p-4"><p class="label-caps">Intent score</p><p class="num mt-2 text-2xl font-semibold text-content">{{lead.score.intent}}</p></div><div class="panel flex items-center justify-between p-4"><div><p class="label-caps">Total score</p><p class="num mt-2 text-2xl font-semibold text-content">{{lead.score.total}} / 100</p></div><ScoreBadge :score="lead.score.total"/></div></div><Panel><Tabs v-model="tab" :items="['Overview','Company','AI Enrichment','Activities','Emails','Notes','Tasks','Calls','Attachments']"/><div v-if="tab==='Overview'" class="grid gap-5 p-5 lg:grid-cols-3"><dl class="grid gap-4 text-xs lg:col-span-2 sm:grid-cols-2"><div v-for="[k,v] in Object.entries({Email:lead.email,Phone:lead.phone,Website:lead.website,LinkedIn:lead.linkedin,Industry:lead.industry,Source:lead.source,Stage:lead.stage,Owner:lead.owner})" :key="k"><dt class="label-caps">{{k}}</dt><dd class="mt-1 text-content">{{v}}</dd></div></dl><div class="rounded-md bg-surface-sunken p-4"><p class="label-caps">Workflow</p><ol class="mt-3 space-y-2 text-xs text-content-secondary"><li>✓ Lead captured</li><li>✓ CRM lead created</li><li :class="lead.enrichment.state==='enriched'?'text-success':''">{{lead.enrichment.state==='enriched'?'✓':'○'}} AI enrichment</li><li>✓ Lead scoring</li><li>{{emails.length?'✓':'○'}} Outreach tracking</li></ol></div></div><div v-else-if="tab==='Company'" class="p-5 text-sm text-content-secondary">{{lead.company}} · {{lead.industry}} · {{lead.size}} employees<br/><span class="text-xs">{{lead.website}}</span></div><div v-else-if="tab==='AI Enrichment'" class="p-5"><div v-if="processing" class="rounded-md bg-surface-sunken p-8 text-center text-sm text-content-muted">Analyzing CRM context, website and profile signals…</div><template v-else><div class="mb-4 flex flex-wrap items-center gap-2"><StatusBadge :status="lead.enrichment.state"/><span class="text-2xs text-content-muted">Last enriched {{lead.enrichment.enrichedAt??'Never'}}</span></div><div class="grid gap-3 lg:grid-cols-2"><AIInsightCard title="Company summary" :content="lead.enrichment.summary"/><AIInsightCard title="Estimated company profile" :content="lead.enrichment.profile"/><AIInsightCard title="Likely pain points" :items="lead.enrichment.painPoints"/><AIInsightCard title="Opportunities" :items="lead.enrichment.opportunities"/><AIInsightCard title="Suggested value proposition" :content="lead.enrichment.valueProposition"/><div class="rounded-md border border-line p-3"><p class="label-caps">Sources</p><ul class="mt-2 text-xs text-content-secondary"><li v-for="x in lead.enrichment.sources" :key="x">{{x}}</li></ul></div></div><div class="mt-4 flex gap-2"><ZButton @click="accepted=true">{{accepted?'Accepted':'Accept data'}}</ZButton><ZButton variant="outline" @click="accepted=false">Discard changes</ZButton></div></template></div><div v-else-if="tab==='Activities'" class="p-4"><ActivityTimeline :items="acts"/></div><div v-else-if="tab==='Emails'" class="divide-y divide-line px-4"><button v-for="x in emails" :key="x.id" class="flex w-full items-center justify-between gap-3 py-3 text-left" @click="selected=x;mailOpen=true"><div><p class="text-sm font-medium text-content">{{x.subject}}</p><p class="text-xs text-content-muted">{{x.sequence}} · Step {{x.step}} · {{x.date}}</p></div><StatusBadge :status="x.status"/></button><AIInsightCard class="my-4" title="Conversation summary" content="Lead showed interest in pricing and requested more information about implementation."/></div><div v-else class="p-10 text-center text-sm text-content-muted">No {{tab.toLowerCase()}} recorded yet.</div></Panel><SidePanel :open="mailOpen" title="Email details" :description="selected?.subject" @close="mailOpen=false"><div v-if="selected" class="space-y-4"><StatusBadge :status="selected.status"/><pre class="whitespace-pre-wrap font-sans text-sm leading-6 text-content-secondary">{{selected.body}}</pre></div></SidePanel></template></AppShell></template>
